        ///     @param inShapeCastSettings Settings for the shape cast
        ///     @param inBaseOffset All hit results will be returned relative to this offset, can be zero to get results in world position, but when you're testing far from the origin you get better precision by picking a position that's closer e.g. inShapeCast.mCenterOfMassStart.GetTranslation() since floats are most accurate near the origin
        ///     @param ioCollector Collector that receives the hits
        ///     @param inBroadPhaseLayerFilter Filter that filters at broadphase level
        ///     @param inObjectLayerFilter Filter that filters at layer level
        ///     @param inBodyFilter Filter that filters at body level
        ///     @param inShapeFilter Filter that filters at shape level
        ///   </code>
        ///   <para>
        ///     Keeps only the closest (or deepest) hit. Returns false, and writes a native default-constructed result
        ///     (e.g. RayCastResult's fraction is 1 + epsilon), when nothing was hit.
        ///   </para>
        /// </remarks>
        public bool CastShapeClosest(
            in RShapeCast shapeCast,
            ShapeCastSettings shapeCastSettings,
            float3 baseOffset,
            out ShapeCastResult result,
            BroadPhaseLayerFilter broadPhaseLayerFilter = default,
            ObjectLayerFilter objectLayerFilter = default,
            BodyFilter bodyFilter = default,
            ShapeFilter shapeFilter = default
        ) =>
            Jolt.PInvoke.NarrowPhaseQuery_CastShapeClosest(
                this,
                in shapeCast,
                shapeCastSettings,
                baseOffset,
                out result,
                broadPhaseLayerFilter,
                objectLayerFilter,
                bodyFilter,
                shapeFilter
            ) != 0;

        /// <summary>
        ///   <para>
        ///     Collect all leaf transformed shapes that fall inside world space box inBox
        ///   </para>
        ///   <para>
        ///     C++:
        ///     <see href="https://github.com/jrouwe/JoltPhysics/blob/e77f175595e64cb44218cc9d9d56fc365ad0e36a/Jolt/Physics/Collision/NarrowPhaseQuery.h#L70">Jolt/Physics/Collision/NarrowPhaseQuery.h:70</see>
        ///     <br/>
        ///     <c>void CollectTransformedShapes(const AABox &amp;inBox, TransformedShapeCollector &amp;ioCollector, const BroadPhaseLayerFilter &amp;inBroadPhaseLayerFilter = { }, const ObjectLayerFilter &amp;inObjectLayerFilter = { }, const BodyFilter &amp;inBodyFilter = { }, const ShapeFilter &amp;inShapeFilter = { }) const</c>
        ///   </para>
        /// </summary>
        /// <remarks>
        ///   <para>
        ///     Returns every shape the query collected as an owned buffer of TransformedShape: Dispose it when done. It
        ///     holds a reference to each shape, so the handles it hands out stay valid until then even if the bodies go
        ///     - but they are borrowed from the buffer, so never Dispose one.
        ///   </para>
        /// </remarks>
        public NativeHandleArray<TransformedShape> CollectTransformedShapes(
            in AABox box,
            BroadPhaseLayerFilter broadPhaseLayerFilter = default,
            ObjectLayerFilter objectLayerFilter = default,
            BodyFilter bodyFilter = default,
            ShapeFilter shapeFilter = default
        ) =>
            new NativeHandleArray<TransformedShape>(
                Jolt.PInvoke.NarrowPhaseQuery_CollectTransformedShapes(
                    this,
                    in box,
                    broadPhaseLayerFilter,
                    objectLayerFilter,
                    bodyFilter,
                    shapeFilter
                )
            );
    }
